head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var tabOpt = {
        label: "임시화면",
        closable: true,
        openAction: "select",
        tabHTML: "scwin.tabHtml",
        addTabIndex: tabControl1.getTabCount()
    };
    var contOpt = {
        "wframe": true,
        "frameDraw": "wframePreload",
        src: "tabControl_addTabTest_WPFF-342_(WSQ-3842)_tmp.xml",
        scope: true,
        title: "iframe title",
    };
    tabControl1.addTab('tab01', tabOpt, contOpt);
};
scwin.tabHtml = function(label) {
    return label + '<input type="button" value="test">';
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'tabControl1_tab_tab01_close').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_tab_tab01_tabHTML').childNodes.length == 2", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
